-- IndieGame table schema
CREATE TABLE indiegame_games (
    -- id: Unique identifier
    id VARCHAR(64) PRIMARY KEY,
    -- domain: Domain
    domain VARCHAR(64) NOT NULL,
    -- id_user: Author (user id)
    id_user VARCHAR(64) NOT NULL,
    -- name: Game name
    name VARCHAR(255) NOT NULL,
    -- description: Game description
    description VARCHAR(200) NOT NULL,
    -- repo_url: Canonical public GitHub repo url
    repo_url VARCHAR(255) NOT NULL,
    -- repo_id: Numeric GitHub repo id (unique)
    repo_id VARCHAR(32) NOT NULL,
    -- screenshots: Screenshot urls (array of strings)
    screenshots VARCHAR(200),
    -- gallery: Gallery image urls (array of strings)
    gallery VARCHAR(200),
    -- video_urls: Gameplay video urls (array of strings)
    video_urls VARCHAR(200),
    -- id_remix_of: Game this one is a remix of (empty for originals)
    id_remix_of VARCHAR(64),
    -- remix_locked: True once the remix link was accepted or confirmed after a report
    remix_locked INTEGER,
    -- status: visible, hidden or deleted
    status VARCHAR(16) NOT NULL,
    -- created: Creation date
    created DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- updated: Last update date
    updated DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Index on domain: Domain
CREATE INDEX idx_indiegame_games_domain ON indiegame_games(domain);

-- Index on id_user: Author (user id)
CREATE INDEX idx_indiegame_games_id_user ON indiegame_games(id_user);

-- Index on repo_id: Numeric GitHub repo id (unique)
CREATE UNIQUE INDEX idx_indiegame_games_repo_id ON indiegame_games(repo_id);

-- Index on id_remix_of: Game this one is a remix of (empty for originals)
CREATE INDEX idx_indiegame_games_id_remix_of ON indiegame_games(id_remix_of);

-- Index on status: visible, hidden or deleted
CREATE INDEX idx_indiegame_games_status ON indiegame_games(status);


